     *
     * - `timeout`: set a maximum timeout
     */
    func tryConnect(timeout: TimeInterval?) async  -> Output
    
    func unsubscribe(subscriptionId: String) async throws  -> Output
    
    func unsubscribeAll() async throws  -> Output
    
    /**
     * Send event
     */
