// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceHandleMonitorNotification {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceHandleMonitorNotification = UniffiVTableCallbackInterfaceHandleMonitorNotification(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeHandleMonitorNotification.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface HandleMonitorNotification: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeHandleMonitorNotification.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface HandleMonitorNotification: handle missing in uniffiClone")
            }
        },
        relayStatusChanged: { (
            uniffiHandle: UInt64,
            relayUrl: UInt64,
            status: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteVoid,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> () in
                guard let uniffiObj = try? FfiConverterTypeHandleMonitorNotification.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return await uniffiObj.relayStatusChanged(
                     relayUrl: try FfiConverterTypeRelayUrl_lift(relayUrl),
                     status: try FfiConverterTypeRelayStatus_lift(status)
                )
            }

            let uniffiHandleSuccess = { (returnValue: ()) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultVoid(
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultVoid(
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsync(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceHandleMonitorNotification> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceHandleMonitorNotification>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitHandleMonitorNotification() {
    uniffi_nostr_sdk_ffi_fn_init_callback_vtable_handlemonitornotification(UniffiCallbackInterfaceHandleMonitorNotification.vtablePtr)
}

