    /**
     * If enabled, NIP-42 will be used for DMs, returning GiftWrap events for
     * the mentioned public key only.
     */
    func authDm(enable: Bool)  -> LocalRelayBuilder
    
    /**
     * Build the local relay
     */
    func build()  -> LocalRelay
    
    /**
     * Set database
     */
    func database(database: NostrDatabase)  -> LocalRelayBuilder
    
    /**
     * Sets the default filter limit when no limit is specified. Defaults 500.
     */
    func defaultFilterLimit(limit: UInt64)  -> LocalRelayBuilder
    
    /**
     * Set number of max connections allowed
     */
    func maxConnections(max: UInt64)  -> LocalRelayBuilder
    
    /**
     * Sets the maximum limit for the filter. If the filter's limit exceeds
     * this value, it will fallback to this number.
     */
    func maxFilterLimit(max: UInt64)  -> LocalRelayBuilder
    
    /**
     * Sets the maximum subscription ID length. Defaults 250.
     */
    func maxSubidLength(max: UInt64)  -> LocalRelayBuilder
    
    /**
     * Sets the minimum Proof of Work difficulty.
     *
     * Only values `> 0` are accepted!
     */
    func minPow(difficulty: UInt8)  -> LocalRelayBuilder
    
    /**
     * Require NIP42 authentication
     */
    func nip42(opts: LocalRelayBuilderNip42)  -> LocalRelayBuilder
    
    /**
     * Set port
     */
    func port(port: UInt16)  -> LocalRelayBuilder
    
    /**
     * Add a query policy plugin
     */
    func queryPolicy(policy: QueryPolicy)  -> LocalRelayBuilder
    
    /**
     * Set rate limit
     */
    func rateLimit(limit: RateLimit)  -> LocalRelayBuilder
    
    /**
     * Add a write policy plugin
     */
    func writePolicy(policy: WritePolicy)  -> LocalRelayBuilder
    
}
