            do {
                try FfiConverterTypeNostrSigner.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface NostrSigner: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeNostrSigner.handleMap.clone(handle: uniffiHandle)
            } catch {
