// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfacePowAdapter {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfacePowAdapter = UniffiVTableCallbackInterfacePowAdapter(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypePowAdapter.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface PowAdapter: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypePowAdapter.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface PowAdapter: handle missing in uniffiClone")
            }
        },
        compute: { (
            uniffiHandle: UInt64,
            unsigned: UInt64,
            difficulty: UInt8,
            uniffiOutReturn: UnsafeMutablePointer<UInt64>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> UnsignedEvent in
                guard let uniffiObj = try? FfiConverterTypePowAdapter.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.compute(
                     unsigned: try FfiConverterTypeUnsignedEvent_lift(unsigned),
                     difficulty: try FfiConverterUInt8.lift(difficulty)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeUnsignedEvent_lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeNostrSdkError_lower
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfacePowAdapter> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfacePowAdapter>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitPowAdapter() {
    uniffi_nostr_sdk_ffi_fn_init_callback_vtable_powadapter(UniffiCallbackInterfacePowAdapter.vtablePtr)
}

