    fileprivate static let handleMap = UniffiHandleMap<PowAdapter>()

    typealias FfiType = UInt64
    typealias SwiftType = PowAdapter

    public static func lift(_ handle: UInt64) throws -> PowAdapter {
        if ((handle & 1) == 0) {
