// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceWritePolicy {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceWritePolicy = UniffiVTableCallbackInterfaceWritePolicy(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeWritePolicy.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface WritePolicy: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeWritePolicy.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface WritePolicy: handle missing in uniffiClone")
            }
        },
        admitEvent: { (
            uniffiHandle: UInt64,
            event: UInt64,
            socketAddr: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> WritePolicyResult in
                guard let uniffiObj = try? FfiConverterTypeWritePolicy.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return await uniffiObj.admitEvent(
                     event: try FfiConverterTypeEvent_lift(event),
                     socketAddr: try FfiConverterString.lift(socketAddr)
                )
            }

            let uniffiHandleSuccess = { (returnValue: WritePolicyResult) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypeWritePolicyResult_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsync(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceWritePolicy> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceWritePolicy>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitWritePolicy() {
    uniffi_nostr_sdk_ffi_fn_init_callback_vtable_writepolicy(UniffiCallbackInterfaceWritePolicy.vtablePtr)
}

