// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Nostr client notification
 */

public enum ClientNotification {
    
    /**
     * Received a new [`Event`] from a relay.
     *
     * This notification is sent only the **first time** the [`Event`] is seen.
     * Events sent by this client are not included.
     * This is useful when you only need to process new incoming events
     * and avoid handling the same events multiple times.
     *
     * If you require notifications for all messages, including previously sent or received events,
     * consider using the [`ClientNotification::Message`] variant instead.
     */
    case newEvent(
        /**
         * The URL of the relay from which the event was received.
         */relayUrl: RelayUrl, 
        /**
         * Subscription ID
         */subscriptionId: String, 
        /**
         * The received event.
         */event: Event
    )
    /**
     * Received a [`RelayMessage`].
     *
     * This notification is sent **every time** a [`RelayMessage`] is received,
     * regardless of whether it has been received before.
     *
     * May includes messages wrapping events that were sent by this client.
     */
    case message(
        /**
         * The URL of the relay from which the message was received.
         */relayUrl: RelayUrl, 
        /**
         * The received relay message.
         */message: RelayMessage
    )
    /**
     * Shutdown
     *
     * This notification variant is sent after [`Client::shutdown`] method is called and all connections have been closed.
     */
    case shutdown





}

#if compiler(>=6)
extension ClientNotification: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeClientNotification: FfiConverterRustBuffer {
    typealias SwiftType = ClientNotification

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClientNotification {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .newEvent(relayUrl: try FfiConverterTypeRelayUrl.read(from: &buf), subscriptionId: try FfiConverterString.read(from: &buf), event: try FfiConverterTypeEvent.read(from: &buf)
        )
        
        case 2: return .message(relayUrl: try FfiConverterTypeRelayUrl.read(from: &buf), message: try FfiConverterTypeRelayMessage.read(from: &buf)
        )
        
        case 3: return .shutdown
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ClientNotification, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .newEvent(relayUrl,subscriptionId,event):
            writeInt(&buf, Int32(1))
            FfiConverterTypeRelayUrl.write(relayUrl, into: &buf)
            FfiConverterString.write(subscriptionId, into: &buf)
            FfiConverterTypeEvent.write(event, into: &buf)
            
        
        case let .message(relayUrl,message):
            writeInt(&buf, Int32(2))
            FfiConverterTypeRelayUrl.write(relayUrl, into: &buf)
            FfiConverterTypeRelayMessage.write(message, into: &buf)
            
        
        case .shutdown:
            writeInt(&buf, Int32(3))
        
        }
    }
}


