     */
    case nip04Decrypt(
        /**
         * Pubkey
         */publicKey: PublicKey, 
        /**
         * Ciphertext
         */ciphertext: String
    )
    /**
     * Encrypt text (NIP44)
     */
    case nip44Encrypt(
        /**
         * Pubkey
         */publicKey: PublicKey, 
        /**
         * Plain text
         */text: String
    )
    /**
     * Decrypt (NIP44)
     */
    case nip44Decrypt(
        /**
         * Pubkey
         */publicKey: PublicKey, 
        /**
         * Ciphertext
         */ciphertext: String
    )
