        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_nostr_sdk_ffi_checksum_func_git_hash_version() != 28105) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nostr_sdk_ffi_checksum_func_init_logger() != 22725) {
        return InitializationResult.apiChecksumMismatch
